;; List Manager error codes;badItemNumber	equ $1C01	;added 5-May-91 DAL (but not used)listRejectEvent	equ $1C02	;added 13-May-91 DAL;=========================================; Offsets for RECT structure.;=========================================y1	equ 0x1	equ y1+2y2	equ x1+2x2	equ y2+2RECTSIZE	equ x2+2;=========================================; Offsets for control structures.;=========================================;; --- General control header ---------------------------------;                                                             CtlNext	equ 0CtlOwner	equ CtlNext+4CtlRect	equ CtlOwner+4CtlFlag	equ CtlRect+RECTSIZECtlHilite	equ CtlFlag+1CtlValue	equ CtlHilite+1CtlProc	equ CtlValue+2CtlAction	equ CtlProc+4CtlData	equ CtlAction+4CtlrefCon	equ CtlData+4CtlColor	equ CtlrefCon+4;; --- Color table offsets ------------------;color1	equ 0color2	equ color1+2color3	equ color2+2color4	equ color3+2color5	equ color4+2color6	equ color5+2color7	equ color6+2color8	equ color7+2;; --- Resource ID numbers;rListRef	equ $801CrCstring	equ $801DrPstring	equ $8006;; --- CtlFlag bit flags --------------------;C_HILITE	equ $00FF	Hilited part, 255 =	inactive.CTL_INVIS	equ $0080	1 if control is invisible.TEST_MEM_NEVER	equ $0040	1 = check the MEM_NEVER bit in the memflag;		0 = don't check MEM_NEVER bit;; ------ CtlFlag bits for scroll bars -------;UP_FLAG	equ $0001	Up arrow.DOWN_FLAG	equ $0002	Down arrow.LEFT_FLAG	equ $0004	Left arrow.RIGHT_FLAG	equ $0008	Right arrow.DIR_SCROLL	equ $0010	0 = vertical, 1 = horizontal scroll.;; ------ CtlFlag bits for simple buttons -----;SB_BOLD	equ $0001;; --- Task numbers ----------------------------;drawCntl	equ 0	Draw the control.calcCRect	equ drawCntl+1	Compute the drag RECT.testCntl	equ calcCRect+1	Perform a hit test on the control.initCntl	equ testCntl+1	Perform additional initialization.dispCntl	equ initCntl+1	Perform additional disposal.posCntl	equ dispCntl+1	Called when dragging complete with delta.thumbCntl	equ posCntl+1	Setup for dragging.dragCntl	equ thumbCntl+1	Perform dragging.autoTrack	equ dragCntl+1	Called while dragging.newValue	equ autoTrack+1	Called when new value is set.setParams	equ newValue+1	Called when min and	max are set.moveCntl	equ setParams+1	Move entire control.recSize	equ moveCntl+1	Return size of control's record.;; --- Task numbers for internal calls----------------------------;ListFirst	equ $8000ListNew	equ $8001ListDrawMem	equ $8002;; --- Part codes for standard controls -----------------;BUTT_PART	equ 2CHECK_PART	equ 3UP_PART	equ 5DOWN_PART	equ 6UPP_PART	equ 7DOWNP_PART	equ 8GROW_PART	equ 10THUMB_PART	equ 129CtlToolNum	equ 16;; --- Control icon numbers -------------------------------;UP_ARROW	equ 8DOWN_ARROW	equ 10LEFT_ARROW	equ 12RITE_ARROW	equ 14GROW_ICON	equ 16TITLE_SPACE	equ 4	Number of pixels added to the width of;                                      	a check box or radio button to get the;                                      	starting X position of the title.;=========================================;          List control record.;=========================================;; --- Extended control record for list control -----------------;CtlMemDraw	equ CtlColor+4	Address of routine to draw members.CtlMemHeight	equ CtlMemDraw+4	Member's height in pixels.CtlMemSize	equ CtlMemHeight+2	Number of bytes in member record.CtlList	equ CtlMemSize+2	Pointer to list control's list.CtlListBar	equ CtlList+4	Handle of list control's scroll bar.;; --- ListRec record offsets ------------------------------------;ListRect	equ 0	List's enclosing RECT.ListSize	equ ListRect+RECTSIZE Total number of members in list.ListView	equ ListSize+2	Max number that can	be viewed at once.ListType	equ ListView+2	Flags.ListStart	equ ListType+2	First member to be displayed.ListCtl	equ ListStart+2	Handle of list's control.ListDraw	equ ListCtl+4	Address of routine to draw members.ListMemHeight	equ ListDraw+4	Member's height in pixels.ListMemSize	equ ListMemHeight+2	Number of bytes in member record.ListPointer	equ ListMemSize+2	Pointer to an array	of string pointers.ListRefCon	equ ListPointer+4	List control's RefCon.ListScrollClr	equ ListRefCon+4	Pointer to scroll bar color table.;; --- MemRec record offsets --------------------------------------;memPtr	equ 0	;bits 0-1 of memFlag indicate typememFlag	equ memPtr+4;; --- memFlag bit values -----------------------------------------;MEM_SEL	equ $0080	TRUE if selected.MEM_DISABLE	equ $0040	TRUE if disabled.MEM_NEVER	equ $0020	TRUE if disabled items cannot be selected;; --- Bit masks for Command and Shift keys -----------------------;COMMAND	equ $0080	Used with state read from $C025.SHIFT	equ $0001;;==========================================;          Event record and flags.;==========================================;what	equ 0message	equ what+2when	equ message+4where	equ when+4modif	equ where+4TaskData	equ modif+2TaskMask	equ TaskData+4;; --- Event codes ----------------------------------------;inNull	equ $00	No further action required.inButtDwn	equ $01	Button down event.inButtUp	equ $02	Button up event.inKey	equ $03	Key event.;	    $04	(Not defined)inAutoKey	equ $05	Auto-Key event.inUpdate	equ $06	Update event.;              	    $07             (Not defined.)inActWind	equ $08	Activate window event.inSwitch	equ $09	Switch event.inAccess	equ $0A	Desk Accessory event.inDevice	equ $0B	Device driver event.;              	    $0C             Application defined.;              	    $0D             Application defined.;             	    $0E             Application defined.;                       $0F             Application defined.;; --- Modifier key flags --------------------------------;K_KEYPAD	equ $2000K_CTRL	equ $1000K_OPTION	equ $0800K_CAPSLOCK	equ $0400K_SHIFT	equ $0200K_COMMAND	equ $0100K_BUTT0	equ $0080K_BUTT1	equ $0040K_CHANGE	equ $0002K_ACTIVE	equ $0001;;=================================================; Equates from procedure ListProc  (ListDP1.asm);=================================================;LastEventCode	equ 1saveFontFlags	equ LastEventCode+2	Save caller's font flag state.strgType	equ saveFontFlags+2	0 = length first, 1	= null terminated.memlist	equ strgType+2	Pointer to locked member list.TextMode	equ memlist+4	Save text writing mode.DisplayTop	equ TextMode+2	Index of first member in display.ViewSize	equ DisplayTop+2	Number of members in display at once.DataSize	equ ViewSize+2	Total number of members.memHeight	equ DataSize+2	Height of member, in pixels.crect	equ memHeight+2	List control's enclosing RECT.cptr	equ crect+8	Pointer to list control.cworkptr	equ cptr+4	;20cworkptr2	equ cworkptr+4FrameClr	equ cworkptr2+4	Color of list control's outline.NorTextClr	equ FrameClr+2	Color of member's text when normal.SelTextClr	equ NorTextClr+2	Color of member's text when selected.NorBackClr	equ SelTextClr+2	Color of normal member's background.SelBackClr	equ NorBackClr+2	Color of selected member's background.curTextClr	equ SelBackClr+2	Current text color.curBackClr	equ curTextClr+2	Current text color.constraint	equ curBackClr+2	bit 0 = shift, bit 7 = open apple.curMember	equ constraint+2	Index of currently selected member.startRange	equ curMember+2	Beginning of selected range.endRange	equ startRange+2	End of selected range.hookMember	equ endRange+2	First member the button went down on.oldClip	equ hookMember+2	Handle of region that holds port's clip.*** theClip	equ oldClip+4	;added 25-Nov-90 DAL for draw1member (now using cWorkPtr2 instead)savezpage	equ oldClip+4returnAddr	equ savezpage+2theControl	equ returnAddr+3parameter	equ theControl+4operation	equ parameter+4result	equ operation+2